,dailyTomorrow:{ru:"Новое блюдо дня — завтра",en:"A new daily special tomorrow"},rewardDaily:{ru:"Блюдо дня",en:"Daily special"},rewardStreak:{ru:"Серия",en:"Streak"},newRecipe:{ru:"Новый рецепт в книге",en:"New in your cookbook"},guestsFed:{ru:"Гостей накормлено: {n}",en:"Guests fed: {n}"},rewardLevel:{ru:"Уровень пройден",en:"Level cleared"},rewardHard:{ru:"Час пик пройден",en:"Rush hour cleared"},rewardSuperhard:{ru:"Банкет удался",en:"Banquet served"},rewardReplay:{ru:"Повтор уровня",en:"Replay"},rewardStars:{ru:"Звёзды",en:"Stars"},rewardClean:{ru:"Без отмен",en:"No undo"},booster_undo:{ru:"Отмена",en:"Undo"},booster_hint:{ru:"Подсказка",en:"Hint"},booster_slot:{ru:"+Место",en:"+Spot"},booster_recipes:{ru:"Рецепты",en:"Recipes"},boosterDesc_hint:{ru:"Показывает безопасный ход — или говорит, что кухню уже не закончить.",en:"Shows a safe next step — or tells you the kitchen can’t be finished."},boosterDesc_slot:{ru:"Ещё одно место на столе до конца уровня.",en:"One more spot on the counter for this level."},boosterUnlocked:{ru:"Новая помощь!",en:"A new helper!"},undoFree:{ru:"Отмена бесплатна, но третья звезда — только без неё.",en:"Undo is free, but the third star needs a clean run."},tut1:{ru:"Нажмите на колонку — верхний продукт попадёт на стол",en:"Tap a column to put its top ingredient on the counter"},tut2:{ru:"Два помидора сами превращаются в соус",en:"Two tomatoes turn into sauce all by themselves"},tut3:{ru:"Макароны + соус = спагетти. Гость ждёт!",en:"Pasta + sauce = spaghetti. Your guest is waiting!"},newDish:{ru:"Новое блюдо!",en:"New dish!"},newRule:{ru:"Новое правило!",en:"New rule!"},intro_spaghetti:{ru:"Макароны и томатный соус. Соус получается сам, когда на столе встречаются два помидора.",en:"Pasta and tomato sauce. Sauce makes itself when two tomatoes meet on the counter."},intro_pizza:{ru:"Тесто, соус и сыр. Тесто получается из муки и яйца.",en:"Dough, sauce and cheese. Flour and an egg make dough."},intro_omelette:{ru:"Яйцо, гриб и сыр. Осторожно: яйцо рядом с мукой станет тестом!",en:"An egg, a mushroom and cheese. Careful: an egg next to flour turns into dough!"},intro_minestrone:{ru:"Зажарка (лук + морковь), картофель и один сырой помидор. Второй помидор превратит его в соус!",en:"Soffritto (onion + carrot), a potato and one raw tomato. A second tomato would turn it into sauce!"},intro_bruschetta:{ru:"Поджаренный хлеб и ОДИН сырой помидор. Второй помидор превратит его в соус!",en:"Toasted bread and ONE raw tomato. A second tomato would turn it into sauce!"},intro_caprese:{ru:"Моцарелла, сырой помидор и базилик — салат, готовить ничего не нужно.",en:"Mozzarella, a raw tomato and basil: a salad, nothing to cook."},intro_risotto:{ru:"Рис, гриб и сыр. Омлету тоже нужны гриб и сыр!",en:"Rice, a mushroom and cheese. The omelette wants the mushroom and the cheese too!"},intro_pesto_pasta:{ru:"Макароны и песто. Песто получается само, когда базилик встречает сыр, — держите базилик подальше от нужного сыра!",en:"Pasta and pesto. Pesto makes itself when basil meets cheese, so keep basil away from cheese you need!"},intro_carbonara:{ru:"Макароны, яйцо, сыр и бекон: четыре части, и яйцо должно держаться подальше от муки.",en:"Pasta, an egg, cheese and bacon: four parts, and the egg must stay away from the flour."},intro_gnocchi:{ru:"Ньокки и томатный соус. Ньокки получаются сами, когда картофель встречает муку.",en:"Gnocchi and tomato sauce. Gnocchi make themselves when a potato meets flour."},intro_calzone:{ru:"Тесто, моцарелла и бекон, сложенные пирожком.",en:"Dough, mozzarella and bacon, folded into a pocket."},intro_tiramisu:{ru:"Крем маскарпоне и кофе. Крем получается сам, когда маскарпоне встречает яйцо, — но мука забирает яйцо первой!",en:"Mascarpone cream and coffee. The cream makes itself when mascarpone meets an egg, but flour grabs the egg first!"},intro_burger:{ru:"Слои собираются снизу вверх, точно по билету.",en:"Layers go on from the bottom up, exactly as the ticket says."},intro_hotdog:{ru:"Булочка, сосиска, потом начинка — снизу вверх, как в билете.",en:"A bun, a sausage, then the toppings, from the bottom up as the ticket says."},intro_pancakes:{ru:"Панкейк на панкейк, топпинг последним. Один и тот же слой дважды — считайте!",en:"Pancake on pancake, the topping last. The same layer twice: count them!"},intro_sandwich:{ru:"Тост снизу и тост сверху: один тост подходит двум тарелкам, и левая забирает его первой.",en:"Toast at the bottom and toast on top: one toast fits two plates, and the left plate takes it first."},intro_sundae:{ru:"Креманка, шарики мороженого и вишенка сверху.",en:"A glass, the scoops and a cherry on top."},intro_tortilla:{ru:"Тортилья ловит начинку: всё, что вы берёте, падает в последнюю открытую тортилью. Три начинки — и тако готово.",en:"A tortilla catches fillings: everything you take drops into the newest open tortilla. Three fillings and the taco folds."},intro_taco_pollo:{ru:"Тако с курицей: курица, сальса и салат. Сальса падает в тортилью сама.",en:"Chicken taco: chicken, salsa and lettuce. The salsa drops into the tortilla by itself."},intro_quesadilla:{ru:"Кесадилья: тортилья, курица и ДВА сыра.",en:"Quesadilla: a tortilla, chicken and TWO helpings of cheese."},intro_enchiladas:{ru:"Энчиладас: в большую лепёшку — курица, фасоль, сыр и сальса.",en:"Enchiladas: chicken, beans, cheese and salsa in a big wrap."},intro_tostada:{ru:"Тостада: фасоль, салат и гуакамоле на хрустящей тортилье.",en:"Tostada: beans, lettuce and guacamole on a crisp tortilla."},intro_park:{ru:"Положите новую тортилью — и начатое тако подождёт. Начинки пойдут в новую.",en:"Lay down a fresh tortilla and the half-made taco waits: fillings go to the new one."},intro_topping:{ru:"Топпинг кладут последним: сыр — на карнитас сверху, салат — на тако с курицей.",en:"Toppings go on last: cheese tops the carnitas, lettuce tops the chicken taco."},intro_burrito_veggie:{ru:"Буррито: большая лепёшка вмещает четыре начинки.",en:"Burritos: a big wrap holds four fillings."},i